def parse_price(s):
    """Parse '$1,234.50', '1.234,50 EUR', '99' into a float."""
    s = s.strip().replace("$", "").replace("EUR", "").strip()
    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        s = s.replace(",", ".")
    return float(s)
